    # Define a dictionary to map each note to its duration in beats
    note_to_beats = {'o':4,'o|':2,'.|':1}

    # Split the input string into individual notes
    notes = music_string.split(' ')

    # Initialize an empty list to store the beat durations
    beats = []

    # Iterate over each note in the list
    for note in notes:
        # Append the corresponding beat duration to the list
        beats.append(note_to_beats[note])

    # Return the list of beat durations
