    for(let [value, symbol] of Object.entries(roman_numerals)){
        // Calculate how many times the current value fits into the number
        let count = Math.floor(number / value);
        // Append the corresponding symbol to the result string the calculated number of times
        mini_roman += symbol.repeat(count);
        // Reduce the number by the value of the current symbol multiplied by the count
        number -= value * count;
    }

    // Return the final roman numeral representation in lowercase
    return mini_roman;
